          if (tab.conn !== rec) return;
          if (typeof ev.data !== 'string') {                                               // binary OUTPUT: [2][uint48 seq][bytes]
            let d;
            try { d = codec.decodeData(new Uint8Array(ev.data), 'server_to_client'); } catch (e) { return protoErr(); }
            if (!rec.opened) return;
